import raw from "@/data/countries.json";
import type { Lang } from "@/features/i18n/messages";
import type { LngLat } from "@/lib/geo";

export type Country = {
  /** ISO 3166-1 numeric, matches the map polygon id. */
  id: string;
  code: string;
  name: Record<Lang, string>;
  capital: Record<Lang, string>;
  lngLat: LngLat;
  areaKm2: number;
};

/** Generated by `pnpm data:countries`; do not edit by hand. */
export const COUNTRIES = raw as unknown as readonly Country[];

const byId = new Map(COUNTRIES.map((c) => [c.id, c]));

export function getCountry(id: string): Country {
  const country = byId.get(id);
  if (!country) throw new Error(`Unknown country id ${id}`);
  return country;
}
